import{_ as r,o as a,c as o,ae as n}from"./chunks/framework.BX6FPmO9.js";const u=JSON.parse('{"title":"錯誤與邊界處理","description":"","frontmatter":{},"headers":[],"relativePath":"conventions/error-handling.md","filePath":"conventions/error-handling.md"}'),t={name:"conventions/error-handling.md"};function i(s,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="錯誤與邊界處理" tabindex="-1">錯誤與邊界處理 <a class="header-anchor" href="#錯誤與邊界處理" aria-label="Permalink to &quot;錯誤與邊界處理&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>本文件簡述 API 與 UI 層的錯誤處理原則，供開發者與 AI 在實作與 code review 時對齊。</p><h2 id="契約層" tabindex="-1">契約層 <a class="header-anchor" href="#契約層" aria-label="Permalink to &quot;契約層&quot;">​</a></h2><ul><li><strong>錯誤 response</strong>：API 回傳錯誤時，形狀應與 <code>app/shared/contracts</code> 內定義一致。既有 <code>errorResponseSchema</code>（<code>{ error: string }</code>）可作為通用錯誤格式；新 API 可沿用或擴充。</li><li><strong>Parse 失敗</strong>：loader / action 或 MSW handler 回傳前應以對應 Zod schema parse；parse 失敗時依專案慣例回傳 4xx/5xx 或統一的錯誤 payload。</li></ul><h2 id="ui-層" tabindex="-1">UI 層 <a class="header-anchor" href="#ui-層" aria-label="Permalink to &quot;UI 層&quot;">​</a></h2><ul><li><strong>顯示</strong>：錯誤訊息以既有 UI 元件（如 <code>Alert</code>）呈現，避免裸 <code>console.error</code> 作為唯一回饋。</li><li><strong>SSE / 串流</strong>：如 ChatInterface 的 EventSource，在 <code>onerror</code> 時應設 error state、關閉連線，並在 UI 顯示可理解的訊息（如「連線中斷，請重試」）。</li></ul><h2 id="與-code-review-的關係" tabindex="-1">與 Code Review 的關係 <a class="header-anchor" href="#與-code-review-的關係" aria-label="Permalink to &quot;與 Code Review 的關係&quot;">​</a></h2><ul><li>新增或變更 API 時，若會回傳錯誤，請在契約中定義或沿用既有 error schema，並在 <a href="./../../specs/api/handler-mapping.html">specs/api/handler-mapping.md</a> 註明。</li><li>審查時可依 <a href="./../code-review-spec.html">Code Review 規範</a> 的「契約與錯誤」項檢查。</li></ul>',9)])])}const m=r(t,[["render",i]]);export{u as __pageData,m as default};
